/** A fixed capsule message kind, keyed in FILL_KINDS (src/main/fill-status-kinds.js). */
export type FillKind = 'setup-enable' | 'setup-account' | 'confirm-heuristic' | 'busy' | 'unsupported-page' | 'page-changed' | 'no-form' | 'no-match' | 'empty-login' | 'nothing-filled' | 'unexpected' | 'desktop-unavailable' | 'account-not-found' | 'not-authorized' | 'session-expired' | 'timed-out' | 'broker-stopped' | 'sdk-error' | 'selection-changed' | 'filled';

/** Capsule mode (MODES in fill-status-kinds.js). */
export type FillMode = 'decision' | 'notice';

/** A capsule button verb: every verb some FILL_KINDS entry allows. */
export type FillVerb = 'open-settings' | 'cancel' | 'fill' | 'dismiss';

/** Show the capsule. Credential-free: fixed ids only. */
export interface FillShowPayload {
  kind: FillKind;
  mode: FillMode;
  /** Per-process counter; replies must echo it. */
  requestId: number;
}

/** Hide the capsule for a request. */
export interface FillHidePayload {
  requestId: number;
}

/** The user picked a verb. main checks the requestId echo and the kind's verb set. */
export interface FillReplyPayload {
  requestId: number;
  verb: FillVerb;
}

/** window.blancFillStatus on blanc-chrome://fill-status/ */
export interface BlancFillStatusAPI {
  /** Show the capsule with a fixed message kind. IPC: event `fill:show`. */
  onShow: (callback: (payload: FillShowPayload) => void) => void;
  /** Hide the capsule. IPC: event `fill:hide`. */
  onHide: (callback: (payload: FillHidePayload) => void) => void;
  /** Answer the capsule. Accepted only from this window's capsule view. IPC: send `fill:reply`. */
  reply: (payload: FillReplyPayload) => void;
}
